    // =====================================================================
    //  LIFECYCLE
    // =====================================================================
    protected override async Task OnInitializedAsync()
    {
        // Đọc cấp học từ localStorage
        await LoadLevelFromStorage();

        // Lấy thông tin user từ AuthenticationState (giống C1_Index)
        var authState = await AuthenticationStateProvider.GetAuthenticationStateAsync();
        var user = authState.User;
        if (user.Identity is not null && user.Identity.IsAuthenticated)
        {
            maUser   = user.FindFirst("MaUser")?.Value ?? string.Empty;
            userRole = user.FindFirst(ClaimTypes.Role)?.Value ?? string.Empty;
        }

        // Lấy session để biết Role (dùng thêm cho CBQL)
        var result = await SessionStorage.GetAsync<UserSession>("UserSession");
        if (result.Success) currentSession = result.Value;

        // Đọc năm học và trường từ localStorage
        SelectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2024-2025";
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);

        // Sinh danh sách năm học options
        GenerateNamHocOptions();

        // Load dữ liệu danh mục
        await LoadDataAsync(SelectedNamHoc);
    }

    // =====================================================================
    //  LEVEL FROM STORAGE
    // =====================================================================
    private async Task LoadLevelFromStorage()
    {
        try
        {
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            if (string.IsNullOrEmpty(selectedCapHoc))
            {
                selectedCapHoc = "02";
                await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", "Cấp Tiểu học");
            }
        }
        catch
        {
            selectedCapHoc = "02";
        }
    }

    // =====================================================================
    //  YEAR / INIT DATA
    // =====================================================================
    private void GenerateNamHocOptions()
    {
        var now = DateTime.Now;
        int year = now.Month >= 9 ? now.Year : now.Year - 1;
        if (string.IsNullOrEmpty(SelectedNamHoc))
            SelectedNamHoc = $"{year}-{year + 1}";

        NamHocOptions = Enumerable.Range(year - 3, 5)
            .Select(y => new OptionModel { Label = $"{y}-{y + 1}", Value = $"{y}-{y + 1}" })
            .ToList();
    }

    private async void HandleNamHocChange(ChangeEventArgs e)
    {
        SelectedNamHoc = e.Value?.ToString() ?? string.Empty;
        SelectedKhoi   = string.Empty;
        SelectedLop    = string.Empty;
        hocSinhList.Clear();
        await LoadDataAsync(SelectedNamHoc);
    }

    private async Task LoadDataAsync(string namHoc)
    {
        try
        {
            isLoading = true;
            StateHasChanged();

            // Load thông tin GV nếu là giáo viên
            if (userRole == "GiaoVien" && !string.IsNullOrEmpty(maUser))
            {
                giaovien = await TruongService.hGetGiaoVienByIdAsync(maUser, maTruongBo, namHoc);
            }

            // Load dữ liệu danh mục
            thData.truong               = await TruongService.hThongTinTruongByID(maTruongBo);
            thData.danhSachKhoiList     = await TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
            thData.danhSachLopList      = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, namHoc);
            thData.danhSachGiaoVienList = await TruongService.hGetDanhSachGiaoVien(maTruongBo, namHoc);
            thData.danhSachMonHocList   = await DaoTaoService.hGetMonHoc(selectedCapHoc);

            // Build options
            BuildKhoiOptions();
            BuildLopOptions();
            BuildMonHocOptions();
            await CheckGiaoVienChuNhiem();

            // Nếu không phải GVCN → chọn mặc định khối/lớp đầu tiên
            SetDefaultKhoiAndLopIfNeeded();

            // Nếu đã có lớp → tải danh sách học sinh luôn
            if (!string.IsNullOrEmpty(SelectedLop))
                await LoadHocSinhData();
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // =====================================================================
    //  FILTER BUILDERS
    // =====================================================================
    private void BuildKhoiOptions()
    {
        KhoiLopOptions = thData.danhSachKhoiList
            .Select(k => new KeyValuePair<object, string>((object)k.MaKhoiBo, k.TenKhoi))
            .ToList();
        UpdateKhoiLopOptions();
    }

    private void BuildLopOptions()
    {
        LopHocOptions = thData.danhSachLopList
            .Select(l => new KeyValuePair<object, string>((object)l.IdLopBo, l.TenLop))
            .ToList();
    }

    private void BuildMonHocOptions()
    {
        MonHocOptions = thData.danhSachMonHocList
            .Select(m => new KeyValuePair<object, string>((object)m.idmonhocso, m.ten_mon_hoc))
            .ToList();
        filteredSubjects = MonHocOptions.ToList();
    }

    private void FilterSubjects()
    {
        filteredSubjects = string.IsNullOrWhiteSpace(searchSubjectText)
            ? MonHocOptions.ToList()
            : MonHocOptions.Where(s =>
                s.Value.Contains(searchSubjectText, StringComparison.OrdinalIgnoreCase) ||
                s.Key.ToString().Contains(searchSubjectText, StringComparison.OrdinalIgnoreCase))
              .ToList();
    }

    private void UpdateKhoiLopOptions()
    {
        FilteredKhoiLopOptions = userRole == "GiaoVien" && IsGiaoVienChuNhiem
            ? KhoiLopOptions.Where(k => k.Key.ToString() == MaKhoiLopChuNhiem).ToList()
            : KhoiLopOptions.ToList();
    }

    private void UpdateLopHocOptions()
    {
        if (userRole == "GiaoVien" && IsGiaoVienChuNhiem)
        {
            FilteredLopHocOptions = LopHocOptions
                .Where(l => l.Key.ToString() == LopChuNhiemId.ToString())
                .ToList();
        }
        else
        {
            FilteredLopHocOptions = LopHocOptions
                .Where(lop =>
                    string.IsNullOrEmpty(SelectedKhoi) ||
                    thData.danhSachLopList.Any(l =>
                        l.IdLopBo.ToString() == lop.Key.ToString() &&
                        l.MaKhoiBo.ToString() == SelectedKhoi))
                .ToList();
        }
    }

    private void SetDefaultKhoiAndLopIfNeeded()
    {
        if (IsGiaoVienChuNhiem) return;

        if (string.IsNullOrEmpty(SelectedKhoi) && FilteredKhoiLopOptions.Any())
            SelectedKhoi = FilteredKhoiLopOptions.First().Key.ToString();

        UpdateLopHocOptions();

        if (string.IsNullOrEmpty(SelectedLop) && FilteredLopHocOptions.Any())
            SelectedLop = FilteredLopHocOptions.First().Key.ToString();
    }

    // =====================================================================
    //  CHANGE HANDLERS
    // =====================================================================
    private async void OnKhoiLopChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;
        SelectedKhoi = e.Value?.ToString() ?? string.Empty;
        SelectedLop  = string.Empty;
        hocSinhList.Clear();
        UpdateLopHocOptions();
        if (FilteredLopHocOptions.Any())
            SelectedLop = FilteredLopHocOptions.First().Key.ToString();
        StateHasChanged();
    }

    private async void OnLopHocChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;
        SelectedLop = e.Value?.ToString() ?? string.Empty;
        hocSinhList.Clear();
        StateHasChanged();
    }

    // =====================================================================
    //  TEACHER CHECK — giống pattern C1_Index
    // =====================================================================
    private async Task CheckGiaoVienChuNhiem()
    {
        if (userRole != "GiaoVien" || giaovien == null) return;

        if (giaovien.ma_lop != null && giaovien.ma_lop > 0)
        {
            IsGiaoVienChuNhiem = true;
            var lopCN = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo == giaovien.ma_lop);
            if (lopCN != null)
            {
                LopChuNhiemId        = lopCN.IdLopBo;
                MaKhoiLopChuNhiem    = lopCN.MaKhoiBo.ToString();
                SelectedLop          = LopChuNhiemId.ToString();
                SelectedKhoi         = MaKhoiLopChuNhiem;
                UpdateKhoiLopOptions();
                UpdateLopHocOptions();
            }
            else
            {
                IsGiaoVienChuNhiem = false;
            }
        }
        else
        {
            IsGiaoVienChuNhiem = false;
        }
    }

    // =====================================================================
    //  MAIN DATA LOAD
    // =====================================================================
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(SelectedLop))
        {
            ShowToast("Vui lòng chọn lớp", "warning");
            return;
        }
        await LoadHocSinhData();
    }

    private async Task LoadHocSinhData()
    {
        try
        {
            isLoadingData = true;
            StateHasChanged();

            // SelectedLop lưu IdLopBo → cần chuyển sang MaLopBo để truyền vào service
            var maLopBo = GetSelectedMaLopBo();
            if (string.IsNullOrEmpty(maLopBo))
            {
                ShowToast("Không tìm thấy mã lớp, vui lòng thử lại", "warning");
                return;
            }
            hocSinhList = await TruongService.hGetHocSinhByLop(maTruongBo, maLopBo, SelectedNamHoc);
            hocSinhList = hocSinhList.OrderBy(hs => hs.SoThuTu).ToList();

            ShowToast(hocSinhList.Any()
                ? $"Đã tải {hocSinhList.Count} học sinh"
                : "Không có học sinh nào trong lớp này",
                hocSinhList.Any() ? "success" : "info");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi tải học sinh: {ex.Message}");
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            hocSinhList = new List<HocSinhDTO>();
        }
        finally
        {
            isLoadingData = false;
            StateHasChanged();
        }
    }

    // =====================================================================
    //  TEMPLATE PATH HELPERS
    // =====================================================================
    private string GetSingleStudentTemplatePath(int hocKy, string isGKorCK)
    {
        string file = (IsKhoi3, IsKhoi, hocKy, isGKorCK) switch
        {
            (true,  _,     1, "GK") => "PhieuDanhGiaHocTapGKI_K3.docx",
            (_,     true,  1, "GK") => "PhieuDanhGiaHocTapGKI_K4_5.docx",
            (_,     _,     1, "GK") => "PhieuDanhGiaHocTapGKI_K1_2.docx",
            (true,  _,     1, "CK") => "PhieuDanhGiaHocTapCKI_K3.docx",
            (_,     true,  1, "CK") => "PhieuDanhGiaHocTapCKI_K4_5.docx",
            (_,     _,     1, "CK") => "PhieuDanhGiaHocTapCKI_K1_2.docx",
            (true,  _,     2, "GK") => "PhieuDanhGiaHocTapGKII_K3.docx",
            (_,     true,  2, "GK") => "PhieuDanhGiaHocTapGKII_K4_5.docx",
            (_,     _,     2, "GK") => "PhieuDanhGiaHocTapGKII_K1_2.docx",
            (true,  _,     2, "CK") => "PhieuDanhGiaHocTapCKII_K3.docx",
            (_,     true,  2, "CK") => "PhieuDanhGiaHocTapCKII_K4_5.docx",
            _                       => "PhieuDanhGiaHocTapCKII_K1_2.docx",
        };
        return Path.Combine(_env.WebRootPath, "Templates", file);
    }

    private string GetExcelTemplatePath(int hocKy, string loaiDanhGia)
    {
        string file = (IsKhoi1_2, IsKhoi3, IsKhoi, hocKy, loaiDanhGia) switch
        {
            (true,  _,     _,     1, "GK") => "BangTongHopDiemGKI_K12.xlsx",
            (_,     true,  _,     1, "GK") => "BangTongHopDiemGKI_K3.xlsx",
            (_,     _,     true,  1, "GK") => "BangTongHopDiemGK_K45.xlsx",
            (true,  _,     _,     1, "CK") => "BangTongHopDiemCKI_K12.xlsx",
            (_,     true,  _,     1, "CK") => "BangTongHopDiemCKI_K3.xlsx",
            (_,     _,     true,  1, "CK") => "BangTongHopDiemCK_K45.xlsx",
            (true,  _,     _,     2, "GK") => "BangTongHopDiemGKII_K12.xlsx",
            (_,     true,  _,     2, "GK") => "BangTongHopDiemGKII_K3.xlsx",
            (_,     _,     true,  2, "GK") => "BangTongHopDiemGKII_K45.xlsx",
            (true,  _,     _,     2, "CK") => "BangTongHopDiemCKII_K12.xlsx",
            (_,     true,  _,     2, "CK") => "BangTongHopDiemCKII_K3.xlsx",
            (_,     _,     true,  2, "CK") => "BangTongHopDiemCKII_K45.xlsx",
            _                               => throw new InvalidOperationException("Không xác định được template phù hợp"),
        };
        return Path.Combine(_env.WebRootPath, "Templates", file);
    }

    private string GetBangTongHopPDFTemplatePath(int hocKy, string loaiDanhGia)
    {
        string khoi = IsKhoi1_2 ? "K12" : IsKhoi3 ? "K3" : IsKhoi ? "K45" : "K12";
        string hocKyText = hocKy == 1 ? "I" : "II";
        if (loaiDanhGia != "GK" && loaiDanhGia != "CK") loaiDanhGia = "CK";
        string suffix = string.IsNullOrEmpty(selectedCBQLForPDF) ? "_KhongKy" : "";
        string templateName = $"BangDiemTongHop{loaiDanhGia}{hocKyText}_{khoi}{suffix}.docx";
        return Path.Combine(_env.WebRootPath, "Templates", templateName);
    }

