    private async Task XuatPDF(HocSinhDTO hs, int hocKy, string loai, bool isPreview)
    {
        if (hs == null) return;
        try
        {
            int lopId = Convert.ToInt32(SelectedLop);

            DGDK_HocSinh    = await DiemService.hGetDanhGiaDinhKyByID(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);
            DGDK_NL_HocSinh = await DiemService.hGetDanhGiaNangLucById(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);
            SucKhoeHocSinh  = await TruongService.hGetThongTinSucKhoe(hs.MaHsSo);

            var mergeFields = loai == "GK" ? CreateMergeFieldsGK(hs) : CreateMergeFieldsCK(hs);

            var templatePath = GetSingleStudentTemplatePath(hocKy, loai);
            if (!File.Exists(templatePath))
            {
                ShowToast($"Không tìm thấy template: {Path.GetFileName(templatePath)}", "warning");
                return;
            }

            string hkText   = hocKy == 1 ? "I" : "II";
            string safeFile = CleanFileName($"{hs.MaHsSo}-{hs.HoTen}-PhieuDG{loai}{hkText}-{DateTime.Now:yyyyMMddHHmmss}.pdf");

            byte[] docBytes = DiemService.GenerateDonNghiPhepWordDocument_Syncfusion(mergeFields, templatePath);
            if (docBytes == null || docBytes.Length == 0)
            {
                ShowToast("Lỗi tạo file PDF", "danger");
                return;
            }

            currentPdfBytes   = docBytes;
            currentPdfStudent = hs;

            if (isPreview)
            {
                pdfViewerUrl    = $"data:application/pdf;base64,{Convert.ToBase64String(docBytes)}";
                showPdfViewer   = true;
                StateHasChanged();
            }
            else
            {
                await DownloadPDFLocally(docBytes, safeFile);
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            Console.WriteLine($"XuatPDF error: {ex}");
        }
    }

    private void ClosePdfViewer()
    {
        showPdfViewer     = false;
        pdfViewerUrl      = string.Empty;
        currentPdfStudent = null;
        currentPdfBytes   = null;
    }

    private async Task PrintCurrentPdf()
    {
        if (currentPdfBytes != null)
            await jsRuntime.InvokeVoidAsync("openPdfInNewTab", Convert.ToBase64String(currentPdfBytes));
    }

    private async Task DownloadCurrentPdf()
    {
        if (currentPdfBytes == null || currentPdfStudent == null) return;
        var name = CleanFileName($"{currentPdfStudent.MaBo}-{currentPdfStudent.HoTen}-PhieuDanhGia-{DateTime.Now:yyyyMMddHHmmss}.pdf");
        await DownloadPDFLocally(currentPdfBytes, name);
    }

    private async Task DownloadPDFLocally(byte[] bytes, string fileName)
    {
        try
        {
            await jsRuntime.InvokeVoidAsync("downloadFileFromBytes",
                Convert.ToBase64String(bytes), "application/pdf", fileName);
        }
        catch (Exception ex) { ShowToast("Da xay ra loi, vui long thu lai!", "error"); }
    }

    // =====================================================================
    //  MERGE FIELDS — SINGLE STUDENT
    // =====================================================================
    private Dictionary<string, string> CreateMergeFieldsGK(HocSinhDTO hs)
    {
        var f  = new Dictionary<string, string>();
        var mc = new MonHocCodeProvider(thData.danhSachMonHocList);
        var nl = DGDK_NL_HocSinh.FirstOrDefault();

        f["TenHocSinh"] = hs.HoTen ?? "";
        f["TenLop"]     = GetTenLop();
        f["TenTruong"]  = thData.truong?.TenTruong ?? "";
        f["MaBo"]       = hs.MaBo ?? "";
        f["GVCN"]       = GetGVCN()?.HoTen ?? "";
        f["SDT"]        = GetGVCN()?.SoDienThoai ?? "";
        f["NgayXuat"]   = DateTime.Now.ToString("dd/MM/yyyy");

        foreach (var (key, maMon) in GetMonHocMap(mc))
            f[key] = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == maMon)?.DgtxGk ?? "";

        f["DTV"] = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == mc.TiengViet)?.DiemGk?.ToString() ?? "";
        f["DTO"] = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == mc.Toan)?.DiemGk?.ToString() ?? "";

        foreach (var (nxKey, maMon) in GetNhanXetMap(mc))
            f[nxKey] = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == maMon)?.NhanXetGk ?? "";

        AddNangLucGK(f, nl);

        f["ngay"]  = DateTime.Now.Day.ToString();
        f["thang"] = DateTime.Now.Month.ToString();
        f["nam"]   = DateTime.Now.Year.ToString();

        return f;
    }

    private Dictionary<string, string> CreateMergeFieldsCK(HocSinhDTO hs)
    {
        var f   = new Dictionary<string, string>();
        var mc  = new MonHocCodeProvider(thData.danhSachMonHocList);
        var nl  = DGDK_NL_HocSinh.FirstOrDefault();
        var sk  = SucKhoeHocSinh.FirstOrDefault();
        var now = DateTime.Now;

        f["TenHocSinh"] = hs.HoTen ?? "";
        f["TenLop"]     = GetTenLop();
        f["TenTruong"]  = thData.truong?.TenTruong ?? "";
        f["MaBo"]       = hs.MaBo ?? "";
        f["GVCN"]       = GetGVCN()?.HoTen ?? "";
        f["SDT"]        = GetGVCN()?.SoDienThoai ?? "";
        f["NgayXuat"]   = now.ToString("dd/MM/yyyy");

        foreach (var (mkKey, maMon) in GetMonHocMap(mc))
        {
            var dg = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == maMon);
            f[$"{mkKey}GK"] = dg?.DgtxGk ?? "";
            f[$"{mkKey}CK"] = dg?.DgtxCk ?? "";
        }

        foreach (var (dKey, maMon) in GetDiemMap(mc))
        {
            var dg = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == maMon);
            f[$"{dKey}GK"] = dg?.DiemGk?.ToString() ?? "";
            f[$"{dKey}CK"] = dg?.DiemCk?.ToString() ?? "";
        }

        foreach (var (nxKey, maMon) in GetNhanXetMap(mc))
        {
            var dg = DGDK_HocSinh.FirstOrDefault(m => m.MaMonHoc == maMon);
            f[$"{nxKey}_GK"] = dg?.NhanXetGk ?? "";
            f[$"{nxKey}_CK"] = dg?.NhanXetCk ?? "";
        }

        AddNangLucGKCK(f, nl);

        f["ChieuCao"]  = sk?.ChieuCao?.ToString() ?? "";
        f["CN"]        = sk?.CanNang?.ToString() ?? "";
        f["TinhTrang"] = sk?.TinhTrangSucKhoe ?? "";

        var cbql = GetCBQL();
        f["TenNguoiQuanLy"] = cbql?.HoTen ?? "";
        f["ChucVu"]          = cbql?.TenChucVu ?? "";
        f["Chucvu"]          = cbql?.TenChucVu ?? "";

        f["Ngay"]  = now.Day.ToString();
        f["Thang"] = now.Month.ToString();
        f["Nam"]   = now.Year.ToString();

        return f;
    }

    // Maps môn học dùng chung
    private IEnumerable<(string key, string maMon)> GetMonHocMap(MonHocCodeProvider mc) =>
        new[]
        {
            ("MKH", mc.KhoaHoc), ("MCN", mc.CongNghe), ("MTH", mc.TinHoc),
            ("MLS", mc.LichSuDiaLy), ("MTV", mc.TiengViet), ("MTO", mc.Toan),
            ("MTN", mc.TuNhienXaHoi), ("MNN", mc.NgoaiNgu), ("MTC", mc.GiaoDucTheChat),
            ("MAN", mc.AmNhac), ("MMT", mc.MiThuat), ("MHD", mc.HoatDongTraiNghiem),
            ("MDD", mc.DaoDuc),
        };

    private IEnumerable<(string key, string maMon)> GetDiemMap(MonHocCodeProvider mc) =>
        new[]
        {
            ("DTV", mc.TiengViet), ("DTO", mc.Toan), ("DNN", mc.NgoaiNgu),
            ("DKH", mc.KhoaHoc), ("DCN", mc.CongNghe), ("DLS", mc.LichSuDiaLy),
            ("DTH", mc.TinHoc),
        };

    private IEnumerable<(string key, string maMon)> GetNhanXetMap(MonHocCodeProvider mc) =>
        new[]
        {
            ("NX_KH", mc.KhoaHoc), ("NX_CN", mc.CongNghe), ("NX_TH", mc.TinHoc),
            ("NX_LS", mc.LichSuDiaLy), ("NX_TV", mc.TiengViet), ("NX_TO", mc.Toan),
            ("NX_TN", mc.TuNhienXaHoi), ("NX_NN", mc.NgoaiNgu), ("NX_TC", mc.GiaoDucTheChat),
            ("NX_AN", mc.AmNhac), ("NX_MT", mc.MiThuat), ("NX_HD", mc.HoatDongTraiNghiem),
            ("NX_DD", mc.DaoDuc),
        };

    private void AddNangLucGK(Dictionary<string, string> f, M_DanhGiaNangLucDTO nl)
    {
        if (nl == null) return;
        f["NMYN"] = nl.Tt22xPcYeuNuocGk ?? "";  f["NMNA"] = nl.Tt22xPcNhanAiGk ?? "";
        f["NMCC"] = nl.Tt22xPcChamChiGk ?? "";   f["NMTT"] = nl.Tt22xPcTtGk ?? "";
        f["NMTN"] = nl.Tt22xPcTnGk ?? "";        f["NMTC"] = nl.Tt22xNlTuChuGk ?? "";
        f["NMGT"] = nl.Tt22xNlGthtGk ?? "";      f["NMGQ"] = nl.Tt22xNlGqvdGk ?? "";
        f["NMNN"] = nl.Tt22xNlNgonNguGk ?? "";   f["NMTO"] = nl.Tt22xNlTinhToanGk ?? "";
        f["NMKH"] = nl.Tt22xNlKhoaHocGk ?? "";   f["NMTM"] = nl.Tt22xNlThamMiGk ?? "";
        f["NMTD"] = nl.Tt22xNlTheChatGk ?? "";   f["NMCN"] = nl.Tt22xNlCongNgheGk ?? "";
        f["NMTH"] = nl.Tt22xNlTinHocGk ?? "";
        f["NNX_NLPC"] = nl.NxpcGk ?? "";
        f["NNX_NLC"]  = nl.NxnlGk ?? "";
        f["NNX_NLDT"] = nl.NxnlDacThuGk ?? "";
    }

    private void AddNangLucGKCK(Dictionary<string, string> f, M_DanhGiaNangLucDTO nl)
    {
        if (nl == null) return;
        void Add(string k, string gk, string ck) { f[$"{k}_GK"] = gk ?? ""; f[$"{k}_CK"] = ck ?? ""; }
        Add("NMYN", nl.Tt22xPcYeuNuocGk, nl.Tt22xPcYeuNuocCk);
        Add("NMNA", nl.Tt22xPcNhanAiGk,  nl.Tt22xPcNhanAiCk);
        Add("NMCC", nl.Tt22xPcChamChiGk, nl.Tt22xPcChamChiCk);
        Add("NMTT", nl.Tt22xPcTtGk,      nl.Tt22xPcTtCk);
        Add("NMTN", nl.Tt22xPcTnGk,      nl.Tt22xPcTnCk);
        Add("NMTC", nl.Tt22xNlTuChuGk,   nl.Tt22xNlTuChuCk);
        Add("NMGT", nl.Tt22xNlGthtGk,    nl.Tt22xNlGthtCk);
        Add("NMGQ", nl.Tt22xNlGqvdGk,    nl.Tt22xNlGqvdCk);
        Add("NMNN", nl.Tt22xNlNgonNguGk,  nl.Tt22xNlNgonNguCk);
        Add("NMTO", nl.Tt22xNlTinhToanGk, nl.Tt22xNlTinhToanCk);
        Add("NMKH", nl.Tt22xNlKhoaHocGk,  nl.Tt22xNlKhoaHocCk);
        Add("NMTM", nl.Tt22xNlThamMiGk,   nl.Tt22xNlThamMiCk);
        Add("NMTD", nl.Tt22xNlTheChatGk,  nl.Tt22xNlTheChatCk);
        Add("NMCN", nl.Tt22xNlCongNgheGk, nl.Tt22xNlCongNgheCk);
        Add("NMTH", nl.Tt22xNlTinHocGk,   nl.Tt22xNlTinHocCk);
        f["NNX_NLPC_GK"] = nl.NxpcGk ?? "";       f["NNX_NLPC_CK"] = nl.NxpcCk ?? "";
        f["NNX_NLC_GK"]  = nl.NxnlGk ?? "";        f["NNX_NLC_CK"]  = nl.NxnlCk ?? "";
        f["NNX_NLDT_GK"] = nl.NxnlDacThuGk ?? "";  f["NNX_NLDT_CK"] = nl.NxnlDacThuCk ?? "";
    }

