    private void ShowExportModal()
    {
        if (string.IsNullOrEmpty(SelectedLop)) { ShowToast("Vui lòng chọn lớp", "warning"); return; }
        if (!hocSinhList.Any()) { ShowToast("Không có học sinh", "warning"); return; }
        showExportModal = true;
        selectedSubjects.Clear();
        searchSubjectText = string.Empty;
        FilterSubjects();
    }

    private void CloseExportModal() { showExportModal = false; selectedSubjects.Clear(); }

    private void ToggleSubjectSelection(string id)
    {
        if (selectedSubjects.Contains(id)) selectedSubjects.Remove(id);
        else selectedSubjects.Add(id);
        StateHasChanged();
    }

    private async Task ExportSelectedSubjects()
    {
        if (!selectedSubjects.Any()) { ShowToast("Chọn ít nhất một môn", "warning"); return; }
        try
        {
            isExporting = true; StateHasChanged();
            if (exportType == "single") await ExportAllSubjectsInOneFile();
            else await ExportSubjectsSeparately();
            CloseExportModal();
        }
        catch (Exception ex) { ShowToast("Da xay ra loi, vui long thu lai!", "error"); }
        finally { isExporting = false; StateHasChanged(); }
    }

    private async Task ExportAllSubjectsInOneFile()
    {
        using var wb = new XLWorkbook();
        foreach (var sid in selectedSubjects)
        {
            var subject = MonHocOptions.FirstOrDefault(m => m.Key.ToString() == sid);
            if (subject.Key == null) continue;
            var ws = wb.Worksheets.Add(TruncateName(subject.Value));
            SetWorksheetHeader(ws, subject.Value);
            int offset = 5;
            if (includeHocKy1) { await AddSubjectDataToWorksheet(ws, sid, 1, offset); offset += hocSinhList.Count + 10; }
            if (includeHocKy2) await AddSubjectDataToWorksheet(ws, sid, 2, offset);
            ws.Columns().AdjustToContents();
        }
        await SaveAndDownloadWorkbook(wb, $"BangDiem_{GetTenLop()}");
        ShowToast($"Đã xuất {selectedSubjects.Count} môn thành công", "success");
    }

    private async Task ExportSubjectsSeparately()
    {
        foreach (var sid in selectedSubjects)
        {
            var subject = MonHocOptions.FirstOrDefault(m => m.Key.ToString() == sid);
            if (subject.Key == null) continue;
            using var wb = new XLWorkbook();
            var ws = wb.Worksheets.Add("Bảng điểm");
            SetWorksheetHeader(ws, subject.Value);
            if (includeHocKy1) await AddSubjectDataToWorksheet(ws, sid, 1, 5);
            if (includeHocKy2) await AddSubjectDataToWorksheet(ws, sid, 2, includeHocKy1 ? hocSinhList.Count + 15 : 5);
            ws.Columns().AdjustToContents();
            await SaveAndDownloadWorkbook(wb, $"BangDiem_{subject.Value}_{GetTenLop()}");
        }
        ShowToast($"Đã xuất {selectedSubjects.Count} file Excel", "success");
    }

    private void SetWorksheetHeader(IXLWorksheet ws, string subjectName)
    {
        ws.Cell(1, 1).Value = "BẢNG ĐIỂM MÔN HỌC";
        ws.Cell(1, 1).Style.Font.Bold = true;
        ws.Cell(1, 1).Style.Font.FontSize = 15;
        ws.Cell(1, 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Range(1, 1, 1, 9).Merge();
        ws.Cell(2, 1).Value = $"Môn: {subjectName}";
        ws.Cell(3, 1).Value = $"Lớp: {GetTenLop()}  |  Năm học: {SelectedNamHoc}";
    }

   private async Task AddSubjectDataToWorksheet(IXLWorksheet ws, string subjectId, int hocKy, int startRow)
    {
        var list = await LoadDanhGiaForExport(subjectId, hocKy);
        ws.Cell(startRow, 1).Value = $"HỌC KỲ {hocKy}";
        ws.Cell(startRow, 1).Style.Font.Bold = true;
        ws.Range(startRow, 1, startRow, 9).Merge();

        var headers = new[] { "STT","Họ tên","Ngày sinh","Mức GK","Điểm GK","Mức CK","Điểm CK","Nhận xét GK","Nhận xét CK" };
        int hRow = startRow + 2;
        for (int i = 0; i < headers.Length; i++)
        {
            var c = ws.Cell(hRow, i + 1);
            c.Value = headers[i];
            c.Style.Font.Bold = true;
            c.Style.Fill.BackgroundColor = XLColor.FromArgb(30, 60, 114);
            c.Style.Font.FontColor = XLColor.White;
            c.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        }

        int dRow = hRow + 1, stt = 1;
        foreach (var hs in hocSinhList)
        {
            var dg = list.FirstOrDefault(d => d.MaHocSinhSo == hs.MaHsSo);
            ws.Cell(dRow, 1).Value = stt++;
            ws.Cell(dRow, 2).Value = hs.HoTen;
            ws.Cell(dRow, 3).Value = hs.NgaySinh.HasValue ? hs.NgaySinh.Value.ToString("dd/MM/yyyy") : "";
            ws.Cell(dRow, 4).Value = dg?.DgtxGk ?? "";
            
            // Xóa ép kiểu (object) và dùng XLCellValue.FromObject để xử lý an toàn
            ws.Cell(dRow, 5).Value = XLCellValue.FromObject(dg?.DiemGk);
            
            ws.Cell(dRow, 6).Value = dg?.DgtxCk ?? "";
            
            // Tương tự cho Điểm CK
            ws.Cell(dRow, 7).Value = XLCellValue.FromObject(dg?.DiemCk);
            
            ws.Cell(dRow, 8).Value = dg?.NhanXetGk ?? "";
            ws.Cell(dRow, 9).Value = dg?.NhanXetCk ?? "";
            dRow++;
        }
    }
    private async Task<List<M_DanhGiaDinhKyDTO>> LoadDanhGiaForExport(string maMonHoc, int hocKy)
    {
        try
        {
            return await DiemService.hGetDanhGiaDinhKy(
                Convert.ToInt32(SelectedLop), hocKy, maMonHoc,
                SelectedNamHoc.Split('-')[0]);
        }
        catch { return new List<M_DanhGiaDinhKyDTO>(); }
    }

    private async Task SaveAndDownloadWorkbook(XLWorkbook wb, string baseName)
    {
        using var stream = new MemoryStream();
        wb.SaveAs(stream);
        stream.Position = 0;
        var fileName = CleanFileName($"{baseName}_{DateTime.Now:yyyyMMddHHmmss}.{exportFormat}");
        using var sr = new DotNetStreamReference(stream);
        await jsRuntime.InvokeVoidAsync("downloadFileFromStream", fileName, sr);
    }

    // =====================================================================
    //  EXCEL EXPORT — BẢNG TỔNG HỢP
    // =====================================================================
    private async Task ExportBangTongHopTheoLop(int hocKy, string loaiDanhGia)
    {
        if (!ValidateBeforeExport()) return;
        try
        {
            isExporting = true;
            StateHasChanged();
            ShowToast("Đang tạo bảng tổng hợp...", "info");

            var templatePath = GetExcelTemplatePath(hocKy, loaiDanhGia);
            if (!File.Exists(templatePath))
            {
                ShowToast($"Không tìm thấy template: {Path.GetFileName(templatePath)}", "danger");
                return;
            }

            using var wb = new XLWorkbook(templatePath);
            var ws = wb.Worksheet(1);
            ws.Name = $"BangTongHop_HK{hocKy}_{loaiDanhGia}";

            FillGeneralInfo(ws);
            await FillStudentData(wb, ws, hocKy, loaiDanhGia);
            FillTeacherInfo(ws);

            using var stream = new MemoryStream();
            wb.SaveAs(stream);
            stream.Position = 0;
            var name = CleanFileName($"BangTongHop_{GetTenLop()}_HK{hocKy}_{loaiDanhGia}_{DateTime.Now:yyyyMMddHHmmss}.xlsx");
            using var sr = new DotNetStreamReference(stream);
            await jsRuntime.InvokeVoidAsync("downloadFileFromStream", name, sr);

            ShowToast("Đã xuất bảng tổng hợp thành công", "success");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            Console.WriteLine($"ExportBangTongHopTheoLop: {ex}");
        }
        finally { isExporting = false; StateHasChanged(); }
    }

    private void FillGeneralInfo(IXLWorksheet ws)
    {
        var gvcn = GetGVCN();
        var now  = DateTime.Now;
        var cbql = GetCBQL();

        foreach (var cell in ws.CellsUsed())
        {
            var v = cell.Value.ToString();
            if (!v.Contains("<<")) continue;
            var original = v;
            v = v.Replace("<<TenLop>>",       GetTenLop())
                 .Replace("<<NamHoc>>",        SelectedNamHoc)
                 .Replace("<<GVCN>>",          gvcn?.HoTen ?? "")
                 .Replace("<<ngay>>",          now.Day.ToString())
                 .Replace("<<thang>>",         now.Month.ToString())
                 .Replace("<<nam>>",           now.Year.ToString())
                 .Replace("<<TenHieuTruong>>", cbql?.HoTen ?? "");
            if (v != original) cell.Value = v;
        }
    }

    private async Task FillStudentData(XLWorkbook wb, IXLWorksheet ws, int hocKy, string loaiDanhGia)
    {
        int startRow = Enumerable.Range(1, 100)
            .FirstOrDefault(r => ws.Cell(r, 1).Value.ToString().Contains("<<STT>>"));
        if (startRow == 0) throw new Exception("Không tìm thấy dòng mẫu <<STT>> trong template");

        string[] sigMarkers = { "<<GVCN>>", "<<ngay>>", "<<TenHieuTruong>>", "GV. Chủ nhiệm", "Hiệu trưởng" };
        int lastRow = ws.LastRowUsed().RowNumber();
        int sigRow = Enumerable.Range(startRow + 1, lastRow - startRow)
            .FirstOrDefault(r => sigMarkers.Any(m => ws.Cell(r, 1).Value.ToString().Contains(m)));
        if (sigRow == 0) sigRow = Math.Min(startRow + 30, lastRow);

        int available = sigRow - startRow - 1;
        if (hocSinhList.Count > available)
        {
            int extra = hocSinhList.Count - available;
            var tempSig = wb.Worksheets.Add("_TempSig");
            for (int i = sigRow; i <= lastRow; i++)
                ws.Row(i).CopyTo(tempSig.Row(i - sigRow + 1));
            ws.Row(sigRow).InsertRowsBelow(extra);
            int newSig = sigRow + extra;
            for (int i = 0; i < lastRow - sigRow + 1; i++)
                tempSig.Row(i + 1).CopyTo(ws.Row(newSig + i));
            wb.Worksheets.Delete("_TempSig");
            sigRow = newSig;
        }

        var tplSheet = wb.Worksheets.Add("_TplRow");
        ws.Row(startRow).CopyTo(tplSheet.Row(1));

        for (int i = 0; i < hocSinhList.Count; i++)
        {
            var hs = hocSinhList[i];
            int curRow = startRow + i;
            if (i > 0) tplSheet.Row(1).CopyTo(ws.Row(curRow));

            int lopId = Convert.ToInt32(SelectedLop);
            DGDK_HocSinh    = await DiemService.hGetDanhGiaDinhKyByID(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);
            DGDK_NL_HocSinh = await DiemService.hGetDanhGiaNangLucById(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);

            var ph = BuildStudentPlaceholders(hs, i, loaiDanhGia);

            for (int col = 1; col <= 40; col++)
            {
                var cell = ws.Cell(curRow, col);
                var cv = cell.Value.ToString();
                if (!cv.Contains("<<")) continue;
                foreach (var kv in ph)
                    cv = cv.Replace(kv.Key, kv.Value);
                cv = Regex.Replace(cv, @"<<[^>]*>>", "");
                cell.Value = cv;
            }
        }

        wb.Worksheets.Delete("_TplRow");
    }

    private Dictionary<string, string> BuildStudentPlaceholders(HocSinhDTO hs, int idx, string loaiDanhGia)
    {
        var mc = new MonHocCodeProvider(thData.danhSachMonHocList);
        var nl = DGDK_NL_HocSinh.FirstOrDefault();
        var ph = new Dictionary<string, string>
        {
            { "<<STT>>",        (idx + 1).ToString() },
            { "<<TenHocSinh>>", hs.HoTen ?? "" },
            { "<<NgaySinh>>",   hs.NgaySinh.HasValue ? hs.NgaySinh.Value.ToString("dd/MM/yyyy") : "" },
            { "<<IsFemale>>",   hs.MaGioiTinh == "Nữ" ? "X" : "" },
        };

        foreach (var (key, maMon) in GetMonHocMap(mc))
        {
            var dg = DGDK_HocSinh.FirstOrDefault(d => d.MaMonHoc == maMon);
            ph[$"<<{key}>>"] = loaiDanhGia == "GK" ? (dg?.DgtxGk ?? "") : (dg?.DgtxCk ?? "");
        }

        foreach (var (dKey, maMon) in GetDiemMap(mc))
        {
            var dg = DGDK_HocSinh.FirstOrDefault(d => d.MaMonHoc == maMon);
            ph[$"<<{dKey}>>"] =
                loaiDanhGia == "CK"
                    ? (dg?.DiemCk?.ToString() ?? "")
                    : loaiDanhGia == "GK" && IsKhoi
                        ? (dg?.DiemGk?.ToString() ?? "")
                        : "";
        }

        AddNangLucToPlaceholders(ph, nl, loaiDanhGia);
        return ph;
    }

    private void AddNangLucToPlaceholders(Dictionary<string, string> ph, M_DanhGiaNangLucDTO nl, string loai)
    {
        if (nl == null) return;
        string G(string gk, string ck) => loai == "GK" ? (gk ?? "") : (ck ?? "");
        ph["<<NMYN>>"] = G(nl.Tt22xPcYeuNuocGk, nl.Tt22xPcYeuNuocCk);
        ph["<<NMNA>>"] = G(nl.Tt22xPcNhanAiGk, nl.Tt22xPcNhanAiCk);
        ph["<<NMCC>>"] = G(nl.Tt22xPcChamChiGk, nl.Tt22xPcChamChiCk);
        ph["<<NMTT>>"] = G(nl.Tt22xPcTtGk, nl.Tt22xPcTtCk);
        ph["<<NMTN>>"] = G(nl.Tt22xPcTnGk, nl.Tt22xPcTnCk);
        ph["<<NMTC>>"] = G(nl.Tt22xNlTuChuGk, nl.Tt22xNlTuChuCk);
        ph["<<NMGT>>"] = G(nl.Tt22xNlGthtGk, nl.Tt22xNlGthtCk);
        ph["<<NMGQ>>"] = G(nl.Tt22xNlGqvdGk, nl.Tt22xNlGqvdCk);
        ph["<<NMNN>>"] = G(nl.Tt22xNlNgonNguGk, nl.Tt22xNlNgonNguCk);
        ph["<<NMTO>>"] = G(nl.Tt22xNlTinhToanGk, nl.Tt22xNlTinhToanCk);
        ph["<<NMKH>>"] = G(nl.Tt22xNlKhoaHocGk, nl.Tt22xNlKhoaHocCk);
        ph["<<NMTM>>"] = G(nl.Tt22xNlThamMiGk, nl.Tt22xNlThamMiCk);
        ph["<<NMTD>>"] = G(nl.Tt22xNlTheChatGk, nl.Tt22xNlTheChatCk);
        ph["<<NMCN>>"] = G(nl.Tt22xNlCongNgheGk, nl.Tt22xNlCongNgheCk);
        ph["<<NMTH>>"] = G(nl.Tt22xNlTinHocGk, nl.Tt22xNlTinHocCk);
    }

