    private async Task ExportBangTongHopLopHocPDF(int hocKy, string loaiDanhGia)
    {
        if (!ValidateBeforeExport()) return;

        cancellationTokenSource = new CancellationTokenSource();
        var token = cancellationTokenSource.Token;

        try
        {
            ShowLoadingOverlay($"Đang tạo bảng tổng hợp PDF", "Quá trình có thể mất vài phút...", hocSinhList.Count);
            isExporting = true;
            StateHasChanged();

            var templatePath = GetBangTongHopPDFTemplatePath(hocKy, loaiDanhGia);
            if (!File.Exists(templatePath))
            {
                HideLoadingOverlay();
                ShowToast($"Không tìm thấy template: {Path.GetFileName(templatePath)}", "danger");
                return;
            }

            var allData = new List<Dictionary<string, string>>();

            for (int i = 0; i < hocSinhList.Count; i++)
            {
                if (token.IsCancellationRequested) { HideLoadingOverlay(); ShowToast("Đã hủy", "warning"); return; }

                var hs = hocSinhList[i];
                currentStudentIndex      = i + 1;
                currentProcessingStudent = hs.HoTen ?? $"#{currentStudentIndex}";
                loadingProgress          = (int)(currentStudentIndex * 88.0 / hocSinhList.Count);
                UpdateLoadingDetails($"Đang xử lý {currentStudentIndex}/{hocSinhList.Count}: {hs.HoTen}");

                try
                {
                    int lopId = Convert.ToInt32(SelectedLop);
                    var t1 = DiemService.hGetDanhGiaDinhKyByID(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);
                    var t2 = DiemService.hGetDanhGiaNangLucById(lopId, hocKy, SelectedNamHoc, hs.MaHsSo);
                    var t3 = TruongService.hGetThongTinSucKhoe(hs.MaHsSo);
                    await Task.WhenAll(t1, t2, t3);

                    var fields = CreateMergeFieldsForBangTongHop(hs, t1.Result, t2.Result, t3.Result, hocKy, loaiDanhGia, i);
                    allData.Add(fields);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Lỗi HS {hs.MaHsSo}: {ex.Message}");
                    allData.Add(CreateMergeFieldsForBangTongHop(hs, new(), new(), new(), hocKy, loaiDanhGia, i));
                }

                if (currentStudentIndex % 3 == 0 || currentStudentIndex == hocSinhList.Count)
                {
                    await InvokeAsync(StateHasChanged);
                    await Task.Delay(1);
                }
            }

            if (token.IsCancellationRequested) { HideLoadingOverlay(); ShowToast("Đã hủy", "warning"); return; }

            loadingProgress = 92;
            UpdateLoadingDetails("Đang tạo nội dung PDF...");
            await InvokeAsync(StateHasChanged);

            var pdfBytes = DiemService.GenerateBangTongHopLopHocPDF(allData, templatePath, hocKy, loaiDanhGia);
            if (pdfBytes == null || pdfBytes.Length == 0)
            {
                HideLoadingOverlay(); ShowToast("Không thể tạo PDF", "danger"); return;
            }

            loadingProgress = 98;
            UpdateLoadingDetails("Đang chuẩn bị tải xuống...");
            await InvokeAsync(StateHasChanged);
            await Task.Delay(200);

            string hkTxt  = hocKy == 1 ? "I" : "II";
            string lDGTxt = loaiDanhGia == "GK" ? "GiuaKy" : "CuoiKy";
            string fileName = CleanFileName($"BangTongHop_{GetTenLop()}_HK{hkTxt}_{lDGTxt}_{DateTime.Now:yyyyMMdd_HHmmss}.pdf");

            loadingProgress = 100; await InvokeAsync(StateHasChanged); await Task.Delay(200);
            await DownloadPDFLocally(pdfBytes, fileName);

            HideLoadingOverlay();
            ShowToast($"Xuất PDF tổng hợp thành công: {fileName}", "success");
        }
        catch (OperationCanceledException) { HideLoadingOverlay(); ShowToast("Đã hủy", "warning"); }
        catch (Exception ex)
        {
            HideLoadingOverlay();
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            Console.WriteLine($"ExportBangTongHopLopHocPDF: {ex}");
        }
        finally
        {
            isExporting = false;
            isCancelling = false;
            cancellationTokenSource?.Dispose();
            cancellationTokenSource = null;
            await InvokeAsync(StateHasChanged);
        }
    }

    private Dictionary<string, string> CreateMergeFieldsForBangTongHop(
        HocSinhDTO hs,
        List<M_DanhGiaDinhKyDTO> dgdk,
        List<M_DanhGiaNangLucDTO> dgnl,
        List<ThongTinSucKhoeHocSinhDTO> sk,
        int hocKy, string loaiDanhGia, int idx)
    {
        var f    = new Dictionary<string, string>();
        var mc   = new MonHocCodeProvider(thData.danhSachMonHocList);
        var nl   = dgnl?.FirstOrDefault();
        var sObj = sk?.FirstOrDefault();
        var key  = (idx + 1).ToString();
        var now  = DateTime.Now;

        f["TenTruong"]      = thData.truong?.TenTruong ?? "";
        f["TenLop"]         = GetTenLop();
        f["NgayXuat"]       = now.ToString("dd/MM/yyyy");
        f["GVCN"]           = GetGVCN()?.HoTen ?? "";
        f["SDT"]            = GetGVCN()?.SoDienThoai ?? "";
        f["Ngay"]           = now.Day.ToString();
        f["Thang"]          = now.Month.ToString();
        f["Nam"]            = now.Year.ToString();
        var cbql = GetCBQL();
        f["TenNguoiQuanLy"] = cbql?.HoTen ?? "";
        f["ChucVu"]         = cbql?.TenChucVu ?? "";
        f["Chucvu"]         = cbql?.TenChucVu ?? "";

        f[$"TenHocSinh_{key}"] = hs.HoTen ?? "";
        f[$"MaBo_{key}"]       = hs.MaBo ?? "";
        f[$"SoNgayNghi_{key}"] = "0";

        f[$"ChieuCao_{key}"]   = sObj?.ChieuCao?.ToString() ?? "";
        f[$"CN_{key}"]         = sObj?.CanNang?.ToString() ?? "";
        f[$"TinhTrang_{key}"]  = sObj?.TinhTrangSucKhoe ?? "";

        foreach (var (mk, maMon) in GetMonHocMap(mc))
        {
            var dg = dgdk?.FirstOrDefault(x => x.MaMonHoc == maMon);
            f[$"{mk}GK_{key}"] = dg?.DgtxGk ?? "";
            f[$"{mk}CK_{key}"] = dg?.DgtxCk ?? "";
        }

        foreach (var (dk, maMon) in GetDiemMap(mc))
        {
            var dg = dgdk?.FirstOrDefault(x => x.MaMonHoc == maMon);
            f[$"{dk}CK_{key}"] = dg?.DiemCk?.ToString() ?? "";
            f[$"{dk}GK_{key}"] = dg?.DiemGk?.ToString() ?? "";
        }

        foreach (var (nxk, maMon) in GetNhanXetMap(mc))
        {
            var dg = dgdk?.FirstOrDefault(x => x.MaMonHoc == maMon);
            f[$"{nxk}_{(loaiDanhGia == "GK" ? "GK" : "CK")}_{key}"] =
                FixUnicode(loaiDanhGia == "GK" ? dg?.NhanXetGk : dg?.NhanXetCk);
        }

        if (nl != null)
        {
            void A(string pre, string gk, string ck)
            {
                f[$"{pre}_GK_{key}"] = NormalizeOneLine(gk);
                f[$"{pre}_CK_{key}"] = NormalizeOneLine(ck);
            }
            A("NMYN", nl.Tt22xPcYeuNuocGk, nl.Tt22xPcYeuNuocCk);
            A("NMNA", nl.Tt22xPcNhanAiGk,  nl.Tt22xPcNhanAiCk);
            A("NMCC", nl.Tt22xPcChamChiGk, nl.Tt22xPcChamChiCk);
            A("NMTT", nl.Tt22xPcTtGk,      nl.Tt22xPcTtCk);
            A("NMTN", nl.Tt22xPcTnGk,      nl.Tt22xPcTnCk);
            A("NMTC", nl.Tt22xNlTuChuGk,   nl.Tt22xNlTuChuCk);
            A("NMGT", nl.Tt22xNlGthtGk,    nl.Tt22xNlGthtCk);
            A("NMGQ", nl.Tt22xNlGqvdGk,    nl.Tt22xNlGqvdCk);
            A("NMNN", nl.Tt22xNlNgonNguGk,  nl.Tt22xNlNgonNguCk);
            A("NMTO", nl.Tt22xNlTinhToanGk, nl.Tt22xNlTinhToanCk);
            A("NMKH", nl.Tt22xNlKhoaHocGk,  nl.Tt22xNlKhoaHocCk);
            A("NMTM", nl.Tt22xNlThamMiGk,   nl.Tt22xNlThamMiCk);
            A("NMTD", nl.Tt22xNlTheChatGk,  nl.Tt22xNlTheChatCk);
            A("NMCN", nl.Tt22xNlCongNgheGk, nl.Tt22xNlCongNgheCk);
            A("NMTH", nl.Tt22xNlTinHocGk,   nl.Tt22xNlTinHocCk);
            f[$"NNX_NLC_GK_{key}"]  = NormalizeOneLine(nl.NxnlGk);
            f[$"NNX_NLC_CK_{key}"]  = NormalizeOneLine(nl.NxnlCk);
            f[$"NNX_NLDT_GK_{key}"] = NormalizeOneLine(nl.NxnlDacThuGk);
            f[$"NNX_NLDT_CK_{key}"] = NormalizeOneLine(nl.NxnlDacThuCk);
            f[$"NNX_NLPC_GK_{key}"] = NormalizeOneLine(nl.NxpcGk);
            f[$"NNX_NLPC_CK_{key}"] = NormalizeOneLine(nl.NxpcCk);
        }

        return f;
    }

