        (thData.danhSachGiaoVienList ?? new List<GiaoVienDTO>())
            .Where(gv => gv.TenChucVu == "Hiệu trưởng" || gv.TenChucVu == "Phó hiệu trưởng")
            .ToList();

    private static string FixUnicode(string s)
        => string.IsNullOrWhiteSpace(s) ? ""
         : s.Normalize(NormalizationForm.FormC).Replace("\u00A0", " ").Trim();

    private static string NormalizeOneLine(string s)
    {
        if (string.IsNullOrWhiteSpace(s)) return "";
        return Regex.Replace(
            s.Normalize(NormalizationForm.FormC).Replace("\u00A0", " ")
             .Replace("\r", " ").Replace("\n", " ").Trim(),
            @"\s+", " ");
    }

    private string TruncateName(string s) => s.Length > 31 ? s[..28] + "..." : s;

    private string CleanFileName(string name)
    {
        if (string.IsNullOrEmpty(name)) return "download.pdf";
        foreach (var c in Path.GetInvalidFileNameChars()) name = name.Replace(c.ToString(), "_");
        return name.Replace(" ", "_").Replace("/", "-").Replace("\\", "-");
    }

    private void ShowToast(string msg, string type = "info")
    {
        toastMessage = msg;
        toastClass   = $"alert-{type}";
        int ms = type == "success" ? 3000 : 4500;
        _ = Task.Delay(ms).ContinueWith(_ => InvokeAsync(() =>
        {
            if (toastMessage == msg) { ClearToast(); StateHasChanged(); }
        }));
    }

    private void ClearToast() { toastMessage = ""; StateHasChanged(); }

    // =====================================================================
    //  MON HOC CODE PROVIDER
    // =====================================================================
    public class MonHocCodeProvider
    {
        private readonly Dictionary<string, string> _map;

        public MonHocCodeProvider(IEnumerable<MonHocDTO> list)
        {
            _map = list?
                .Where(m => !string.IsNullOrWhiteSpace(m.ten_mon_hoc))
                .ToDictionary(m => m.ten_mon_hoc.Trim(), m => m.idmonhocso?.Trim() ?? "")
                ?? new();
        }

        private string Get(string name)
            => _map.TryGetValue(name.Trim(), out var v) ? v : "";

        public string Toan               => Get("Toán");
        public string TiengViet          => Get("Tiếng Việt");
